      outputs: ['Hello', 'World'],
      references: ['hello', 'world']
    });

    const thresholds = { exact_match: 0.5 };
    const report = generateReport({
      evaluations,
      outputsPath: '/tmp/outputs.json',
      referencesPath: '/tmp/refs.json',
      thresholds
    });

    expect(report).toHaveProperty('passed');
    expect(report).toHaveProperty('thresholds');
    expect(Array.isArray(report.thresholds)).toBe(true);
    expect(report.thresholds.length).toBeGreaterThan(0);
  });

  it('report without thresholds does not include threshold fields', () => {
    const evaluations = runEvaluations({
      outputs: ['Hello'],
      references: ['hello']
    });

    const report = generateReport({
      evaluations,
      outputsPath: '/tmp/outputs.json',
      referencesPath: '/tmp/refs.json'
    });

    expect(report).not.toHaveProperty('passed');
    expect(report).not.toHaveProperty('thresholds');
  });
});

