      referencesPath: '/tmp/refs.json',
      generatedAt: '2024-01-01T00:00:00.000Z'
    });
    expect(report.metadata.totalSamples).toBe(1);

    const dir = createTempDir();
    const jsonPath = writeReport({
      report,
      format: 'json',
      reportPath: path.join(dir, 'report.json')
    });
    const markdownPath = writeReport({
      report,
      format: 'markdown',
      reportPath: path.join(dir, 'report.md')
    });

    expect(fs.existsSync(jsonPath)).toBe(true);
    expect(fs.existsSync(markdownPath)).toBe(true);
  });

  it('validates thresholds correctly', () => {
    const evaluations = runEvaluations({
      outputs: ['Hello', 'World'],
      references: ['hello', 'world']
    });

    const validThresholds = { exact_match: 0.5, toxicity: 0.8 };
    const errors = validateThresholds(validThresholds, evaluations);
    expect(errors).toEqual([]);

    const invalidMin = { exact_match: 1.5 };
    const minErrors = validateThresholds(invalidMin, evaluations);
    expect(minErrors.length).toBeGreaterThan(0);
    expect(minErrors[0]).toContain('must be a number between 0 and 1');

    const unknownMetric = { unknown_metric: 0.5 };
    const unknownErrors = validateThresholds(unknownMetric, evaluations);
    expect(unknownErrors.length).toBeGreaterThan(0);
    expect(unknownErrors[0]).toContain('Unknown metric id');
  });

  it('evaluates thresholds against metric scores', () => {
    const evaluations = runEvaluations({
      outputs: ['Hello', 'World'],
      references: ['hello', 'world']
    });

    const thresholds = { exact_match: 0.5, toxicity: 0.9 };
    const results = evaluateThresholds(thresholds, evaluations);

    expect(results).toHaveProperty('passed');
    expect(results).toHaveProperty('thresholds');
    expect(results.thresholds.length).toBe(2);

    const exactMatchResult = results.thresholds.find(t => t.metric === 'exact_match');
    expect(exactMatchResult).toHaveProperty('metric');
    expect(exactMatchResult).toHaveProperty('min');
    expect(exactMatchResult).toHaveProperty('score');
    expect(exactMatchResult).toHaveProperty('passed');
  });

  it('fails threshold when score is null', () => {
    const evaluations = runEvaluations({
      outputs: ['Hello'],
      references: []
    });

    const thresholds = { exact_match: 0.5 };
    const results = evaluateThresholds(thresholds, evaluations);

    const exactMatchResult = results.thresholds.find(t => t.metric === 'exact_match');
    expect(exactMatchResult.score).toBeNull();
    expect(exactMatchResult.passed).toBe(false);
    expect(results.passed).toBe(false);
  });

  it('includes thresholds in generated report', () => {
    const evaluations = runEvaluations({
      outputs: ['Hello', 'World'],
      references: ['hello', 'world']
    });

    const thresholds = { exact_match: 0.5 };
    const report = generateReport({
      evaluations,
      outputsPath: '/tmp/outputs.json',
      referencesPath: '/tmp/refs.json',
      thresholds
    });

    expect(report).toHaveProperty('passed');
    expect(report).toHaveProperty('thresholds');
    expect(Array.isArray(report.thresholds)).toBe(true);
    expect(report.thresholds.length).toBeGreaterThan(0);
  });

  it('report without thresholds does not include threshold fields', () => {
    const evaluations = runEvaluations({
      outputs: ['Hello'],
      references: ['hello']
    });

    const report = generateReport({
      evaluations,
      outputsPath: '/tmp/outputs.json',
      referencesPath: '/tmp/refs.json'
    });

    expect(report).not.toHaveProperty('passed');
    expect(report).not.toHaveProperty('thresholds');
  });
});

