380	function parseThresholds(thresholdStrings = []) {
381	    if (!thresholdStrings || thresholdStrings.length === 0) {
382	        return null;
383	    }
384	    const thresholds = {};
385	    for (const threshStr of thresholdStrings) {
386	        const parts = threshStr.split('=');
387	        if (parts.length !== 2) {
388	            log.error(`Invalid threshold format: '${threshStr}'. Expected format: <metric>=<number>`);
389	            process.exit(2);
390	        }
391	        const metricId = parts[0].trim();
392	        const minStr = parts[1].trim();
393	        const minimum = Number.parseFloat(minStr);
394	        if (Number.isNaN(minimum) || minimum < 0 || minimum > 1) {
395	            log.error(`Invalid minimum for metric '${metricId}': must be a number between 0 and 1, got '${minStr}'`);
396	            process.exit(2);
397	        }
398	        thresholds[metricId] = minimum;
399	    }
400	    return thresholds;
401	}
402	function runEvalCommand(options) {
403	    assertFileExists(options.outputs);
