414	    if (thresholds) {
415	        const validationErrors = Eval.validateThresholds(thresholds, evaluations);
416	        if (validationErrors.length > 0) {
417	            validationErrors.forEach((error) => log.error(error));
418	            process.exit(2);
419	        }
420	    }
421	    const report = Eval.generateReport({
422	        evaluations,
