424	        referencesPath: dataset.referencesPath,
425	        thresholds: thresholds || {}
426	    });
427	    const resolvedPath = Eval.writeReport({
428	        report,
429	        format: options.format ?? 'json',
430	        reportPath: options.report
431	    });
432	    log.success('Evaluation report generated.', { path: resolvedPath });
433	    // Exit with error code if any threshold failed
434	    if (report.passed === false) {
435	        process.exit(1);
436	    }
437	}
